"""苏联：南翼主要坦克师与步兵师（south 代理）。"""
from south_lib import unit, near, mid, detrack, iso
import south_su_hq

B = ('boe_1941', 'glantz_initial')
BR = ('south_wiki_brody_ru', 'south_wiki_brody_en') + B
UM = ('south_wiki_uman',) + B
KV = ('stahel_kiev', 'south_wiki_kiev') + B
OD = ('south_wiki_odessa_ru', 'south_wiki_odessa_en') + B
CR = ('south_wiki_crimea_ru',) + B


def build():
    H = {u['id']: u for u in south_su_hq.build()}
    U = []

    def div(uid, zh, orig, short, par, typ, cmd, base, dx, dy, extra=(), hist='', conf='medium', src=B, since=None, until=None, frm=None, men=None, tanks=None, model='inf_su', equip=None):
        trk = detrack(H[base], dx, dy, since=since, until=until) if base else []
        pts = {iso(t[0]): t for t in trk}
        for e in extra:
            pts[iso(e[0])] = e
        trk = [pts[k] for k in sorted(pts)]
        U.append(unit(uid, 'SU', 'division', typ, par, zh, orig, short, cmd=cmd, men=men, tanks=tanks, model=model, equip=equip, frm=frm,
                      trk=tuple(trk), hist=hist, src=src, conf=conf))

